// 整卷难度曲线：真实试卷按 前易-中段-后难 分布（约 30/50/20）
export function diffCurve(i, n) {
  const r = n > 1 ? i / (n - 1) : 0
  if (r < 0.3) return 'easy'
  if (r < 0.8) return 'mid'
  return 'hard'
}

