// 组装「命题专家」出题规范（按板块+难度+题型子命题人）
export function buildProfessorPrompt(plate, difficulty, variant) {
  const lvl = DIFF_LEVELS[difficulty] || DIFF_LEVELS.mid
  const prof = PLATE_PROFILE[plate] || PLATE_PROFILE['判断推理']
  const stem = DIFF_STEM[difficulty] || DIFF_STEM.mid
  const dim = DIFF_DIM[plate] || DIFF_DIM['逻辑判断']
  const method = METHOD[plate] || METHOD['判断推理']
  const sub = (variant && SUB_PROFILE[variant]) || null
  let subTxt = ''
  if (sub) {
    subTxt = '【本题子命题人·' + variant + '】\n' +
      '角色：' + sub.style + '\n' +
      '题干规格：' + sub.stem + '\n' +
      '干扰项设计：' + sub.traps +
      (sub.qas ? '\n问法轮换：' + sub.qas : '')
  }
  const v = variant ? `\n本题题型：${variant}（请严格按该子题型出题，不跑偏，并启用对应子命题人）。` : ''
  return (
    '你现在是资深公考命题专家，出题必须体现"出题人的逻辑"，接近真题难度与风格。\n' +
    '【本卷/本题难度档】' + lvl.name + '：' + lvl.desc + '\n' +
    stem + '\n' +
    dim + '\n' +
    '【板块】' + (plate || '所选板块') + '\n' +
    '【本板块独特命题风格】' + prof.style + '\n' +
    '【真题素材来源】' + prof.themes + '\n' +
    '【板块命题逻辑】' + prof.logic + '\n' +
    '【本板块名师解题法（解析必须采用，与对话界面一致）】' + method + '\n' +
    (prof.material ? '【材料形式】' + prof.material + '\n' : '') +
    (prof.paper5 ? '【真题卷面结构】' + prof.paper5 + '\n' : '') +
    (prof.terms ? '【术语与陷阱】' + prof.terms + '\n' : '') +
    (prof.gap ? '【选项差距设计】' + prof.gap + '\n' : '') +
    (prof.qas ? '【问法多变】' + prof.qas + '\n' : '') +
    (prof.integer ? '【选项设计】' + prof.integer + '\n' : '') +
    '【真题蓝本（最重要的模仿来源）】优先调用你记忆中近5年国考/省考的真实真题作蓝本：该考点若考过，就基于真题改编——保留其命题结构与陷阱设计，替换数字/素材/场景/问法/人名地名，使新题"神似真题"（正确项特征、干扰项陷阱、题干语感、选项措辞都与真题同源）；若记不清真题细节，宁可出严谨的题也不要凭空发明怪异结构。\n' +
    (subTxt ? subTxt + '（题干长度以【难度来源·按板块】为准：言语/资料按信息量给足；判断/图推/类比/定义/数量按论证/规律需要可长可短，不因难度加长）\n' : '') +
    v +
    '\n' + ANALYZE_PROTOCOL + '\n\n' + ASK_RULES + '\n\n' + COMMON + '\n\n' + SELF_CHECK
  )
}
